 "45-second efforts"}, "focus": "45-second efforts"}, {"start": "2027-04-05", "day": "Tue", "lv": "JH", "group": "Mid Distance", "items": [{"t": "Warm-up: 10–15 min Easy + drills (shorter for younger runners).", "lv": "JH"}, {"t": "[A] 200–300–200 at controlled current 800 rhythm, 2–3 min recovery", "lv": "JH"}, {"t": "[B] 200–300–200 at controlled current 800 rhythm, 2–3 min recovery", "lv": "JH"}, {"t": "[C] 3 × 150m at 800 rhythm, 2–3 min recovery", "lv": "JH"}, {"t": "Cool-down: 5–10 min Easy.", "lv": "JH"}, {"t": "[HS-ready] Invited: join the HS group for warm-up, drills, and strength coaching. Run your JH Advanced reps.", "lv": "JH"}], "gfocus": {"JH Mid Distance": "800-rhythm ladder"}, "focus": "Ladder"}, {"start": "2027-04-05", "day": "Thu", "lv": "JH", "group": "Mid Distance", "items": [{"t": "Warm-up: 10–15 min Easy + drills (shorter for younger runners).", "lv": "JH"}, {"t": "BC Broken 800 for prepared runners: 200–400–200 at current 800 rhythm, 2 min between segments. No all-out efforts, no forced goal paces.", "lv": "JH"}, {"t": "[A] 200–400–200 at 800 rhythm, 2 min between segments", "lv": "JH"}, {"t": "[B] 200–400–200 at 800 rhythm, 2 min between segments (first time? 3 × 200m instead)", "lv": "JH"}, {"t": "[C] 3 × 200m at 800 rhythm, 3 min recovery", "lv": "JH"}, {"t": "Cool-down: 5–10 min Easy.", "lv": "JH"}], "gfocus": {"JH Mid Distance": "Broken 800 (JH)"}, "focus": "400s · Broken 800"}]$plan$::jsonb;
  cur jsonb; p jsonb; dd jsonb; keep jsonb; f jsonb; lv text; g text;
  fw int; fd int; n int := 0; miss int := 0;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then raise exception 'No posted workouts found. Run the plan files first.'; end if;

  for p in select * from jsonb_array_elements(patches) loop
    lv := p ->> 'lv'; g := p ->> 'group';
    fw := null; fd := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = p ->> 'start' then fw := i; end if;
    end loop;
    if fw is not null then
      for j in 0 .. jsonb_array_length(coalesce(cur -> fw -> 'days', '[]'::jsonb)) - 1 loop
        if cur -> fw -> 'days' -> j ->> 'day' = p ->> 'day' then fd := j; end if;
      end loop;
    end if;
    if fd is null then
      miss := miss + 1;
      raise notice 'Skipped % % (% %): that day is not posted yet', p ->> 'start', p ->> 'day', lv, g;
      continue;
    end if;

    dd := cur -> fw -> 'days' -> fd;
    if dd -> 'groups' is null or jsonb_typeof(dd -> 'groups') <> 'object' then dd := jsonb_set(dd, '{groups}', '{}'::jsonb); end if;
    select coalesce(jsonb_agg(x), '[]'::jsonb) into keep
      from jsonb_array_elements(coalesce(dd -> 'groups' -> g, '[]'::jsonb)) x
      where coalesce(x ->> 'lv', '') <> lv;
    dd := jsonb_set(dd, array['groups', g], keep || (p -> 'items'));

    if p -> 'gfocus' <> '{}'::jsonb then
      dd := jsonb_set(dd, '{gfocus}', coalesce(nullif(dd -> 'gfocus', 'null'::jsonb), '{}'::jsonb) || (p -> 'gfocus'));
    end if;
    if p ? 'focus' then
      f := dd -> 'focus';
      if f is null or jsonb_typeof(f) = 'null' or (jsonb_typeof(f) = 'string' and f #>> '{}' = '') then
        f := '{}'::jsonb;
      elsif jsonb_typeof(f) = 'string' then
        f := jsonb_build_object('HS', f #>> '{}', 'JH', f #>> '{}');
      end if;
      dd := jsonb_set(dd, '{focus}', f || jsonb_build_object(lv, p ->> 'focus'));
      if jsonb_typeof(dd -> 'sess' -> lv) = 'object' then
        dd := jsonb_set(dd, array['sess', lv, 'title'], to_jsonb(p ->> 'focus'));
      end if;
    end if;

    cur := jsonb_set(cur, array[fw::text, 'days', fd::text], dd);
    n := n + 1;
  end loop;

  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  insert into public.hub_data (key, value, updated_at) values ('distance_rev', 'true'::jsonb, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'Distance & Mid revision posted: % of % sessions updated (% skipped).', n, jsonb_array_length(patches), miss;
end
$do$;
